import json
import os

import jax
import jax.numpy as jnp
import numpy as np


def basic_reduce(x):
    return jnp.mean(x, axis=1)


def map_square(x):
    # Explicit vectorization across rows
    return jax.vmap(lambda row: row**2)(x)


def grad_logistic(data):
    x = jnp.asarray(data["x"])
    y = jnp.asarray(data["y"])
    w0 = jnp.asarray(data["w"])

    def loss_fn(w):
        logits = x @ w
        # y in {-1, 1}
        return jnp.mean(jnp.logaddexp(0.0, -y * logits))

    return jax.grad(loss_fn)(w0)


def scan_rnn(data):
    seq = jnp.asarray(data["seq"])
    init = jnp.asarray(data["init"])
    Wx = jnp.asarray(data["Wx"])
    Wh = jnp.asarray(data["Wh"])
    b = jnp.asarray(data["b"])

    def step(h, x):
        h_new = jnp.tanh(Wx @ x + Wh @ h + b)
        return h_new, h_new

    _, hs = jax.lax.scan(step, init, seq)
    return hs


def jit_mlp(data):
    X = jnp.asarray(data["X"])
    W1 = jnp.asarray(data["W1"])
    b1 = jnp.asarray(data["b1"])
    W2 = jnp.asarray(data["W2"])
    b2 = jnp.asarray(data["b2"])

    @jax.jit
    def mlp(x):
        h = jnp.maximum(0.0, x @ W1 + b1)
        return h @ W2 + b2

    return mlp(X)


def main():
    root = os.path.dirname(os.path.abspath(__file__))
    with open(os.path.join(root, "problem.json"), "r") as f:
        tasks = json.load(f)

    for task in tasks:
        task_id = task["id"]
        input_path = os.path.join(root, task["input"])
        output_path = os.path.join(root, task["output"])

        if task_id in {"basic_reduce", "map_square"}:
            x = jnp.asarray(np.load(input_path))
            if task_id == "basic_reduce":
                out = basic_reduce(x)
            else:
                out = map_square(x)
        elif task_id == "grad_logistic":
            data = np.load(input_path)
            out = grad_logistic(data)
        elif task_id == "scan_rnn":
            data = np.load(input_path)
            out = scan_rnn(data)
        elif task_id == "jit_mlp":
            data = np.load(input_path)
            out = jit_mlp(data)
        else:
            raise ValueError(f"Unknown task id: {task_id}")

        np.save(output_path, np.array(out))


if __name__ == "__main__":
    main()
